from typing import Tuple, List
import bisect
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for serialized character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and basic shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length using binary search and C-level string slicing."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse as LCPs of lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(cls._lcp(ordered[i - 1], ordered[i])
                   for i in range(1, len(ordered)))

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific source-column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by length-weighted repeated-value savings."""
        n, m = cells.shape
        ranked = []
        for column in range(m):
            counts = {}
            total = 0
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeated = sum(count * (count - 1)
                            for count in counts.values())

            if mode == 0:
                score = weighted
            else:
                score = repeated * max(1, total // max(1, n))

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Use one repeated leading field, then rank remaining fields independently per group."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_scores = []
        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_scores.append((score, column))

        lead_scores.sort(key=lambda item: (-item[0], item[1]))
        lead = lead_scores[0][1]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            scores = []
            for column in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, column]
                    counts[value] = counts.get(value, 0) + 1
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                scores.append((score, column))

            scores.sort(key=lambda item: (-item[0], item[1]))
            order = [lead] + [column for _, column in scores]
            for row in rows:
                result[row] = order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize a candidate and return its exact score and sorted row order."""
        strings = self._make_strings(cells, orders)
        row_order = sorted(range(len(strings)),
                           key=lambda row: (strings[row], row))
        return self._trie_score(strings), strings, row_order

    def _local_row_refine(self, cells, raw, orders, strings):
        """Apply at most 96 exact row-specific column moves using neighboring-LCP deltas."""
        n, m = cells.shape
        if n < 2 or m < 2:
            return strings, orders

        # Entries are kept in the same deterministic order used by the exact objective.
        entries = sorted((strings[row], row) for row in range(n))
        current_score = sum(
            self._lcp(entries[i - 1][0], entries[i][0])
            for i in range(1, len(entries))
        )

        # Rows with weak neighboring prefixes are the most promising local targets.
        weakness = []
        for i, (text, row) in enumerate(entries):
            left = self._lcp(entries[i - 1][0], text) if i else 0
            right = self._lcp(text, entries[i + 1][0]) if i + 1 < n else 0
            weakness.append((left + right, -len(text), row))
        weakness.sort()
        selected = [item[2] for item in weakness[:min(6, n)]]

        attempts = 0
        for row in selected:
            if attempts >= 96:
                break

            old_order = orders[row][:]
            ranked_columns = sorted(
                old_order,
                key=lambda column: (-len(cells[row, column]), column)
            )[:min(16, m)]

            for moved in ranked_columns:
                if attempts >= 96:
                    break

                # A column move considers both permitted destinations as one proposal.
                positions = [0, 1] if m > 1 else [0]
                best_trial = None

                old_text = strings[row]
                old_key = (old_text, row)
                old_index = bisect.bisect_left(entries, old_key)
                while old_index < len(entries) and entries[old_index] != old_key:
                    old_index += 1
                if old_index >= len(entries):
                    continue

                affected = set()
                for index in (old_index - 1, old_index, old_index + 1):
                    if 0 < index < len(entries):
                        affected.add(index)
                old_local = sum(
                    self._lcp(entries[i - 1][0], entries[i][0])
                    for i in affected
                )

                removed = entries[:old_index] + entries[old_index + 1:]

                for destination in positions:
                    trial_order = old_order[:]
                    trial_order.remove(moved)
                    trial_order.insert(destination, moved)
                    trial_text = "".join(
                        cells[row, column] for column in trial_order
                    )
                    trial_key = (trial_text, row)
                    insert_at = bisect.bisect_left(removed, trial_key)

                    new_affected = set()
                    for index in (insert_at, insert_at + 1):
                        if 0 < index < len(removed):
                            new_affected.add(index)

                    new_local = sum(
                        self._lcp(removed[i - 1][0], removed[i][0])
                        for i in new_affected
                    )
                    delta = new_local - old_local

                    if best_trial is None or delta > best_trial[0]:
                        best_trial = (
                            delta, trial_order, trial_text, insert_at
                        )

                attempts += 1
                if best_trial is None or best_trial[0] <= 0:
                    continue

                delta, new_order, new_text, insert_at = best_trial
                entries = removed[:insert_at] + [(new_text, row)] + removed[insert_at:]
                orders[row] = new_order
                strings[row] = new_text
                current_score += delta

        # Return the final deterministic sorted order to the caller.
        entries.sort()
        return strings, orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate bounded global and conditional candidates, then refine selected rows locally."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._conditional_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))
            if best is None or choice > best[0]:
                best = (choice, strings, row_order, [order[:] for order in orders])

        _, strings, _, orders = best
        strings, orders = self._local_row_refine(cells, raw, orders, strings)

        row_order = sorted(range(n), key=lambda row: (strings[row], row))
        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            order = orders[source]
            output[destination, :] = [raw[source, column] for column in order]
            column_orders.append([df.columns[column] for column in order])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

